const noContext = 'No se encontró material relevante sobre el tema en la base de datos.';
  const sources = [];
  const seen = new Set();
  let remaining = 28000;
  for (const item of $input.all()) {
    const doc = item.json.document || item.json;
    const raw = doc.pageContent || doc.text || '';
    const text = typeof raw === 'string' ? raw.trim() : '';
    if (!text) continue;
    const metadata = doc.metadata || {};
    const source = String(metadata.archivo || metadata.sourceFile || metadata.filename || metadata.source || 'Material del curso');
    const rawPage = metadata.pagina ?? metadata.page ?? metadata.pageNumber ?? metadata['loc.pageNumber'] ?? metadata.loc?.pageNumber;
    const number = Number(rawPage);
    const page = Number.isInteger(number) && number > 0 ? number : null;
    const key = JSON.stringify([source, page, text.replace(/\s+/g, ' ')]);
    if (seen.has(key)) continue;
    seen.add(key);
    const header = 'Fuente: ' + source + (page ? ' (Pág. ' + page + ' del PDF)' : '') + '\n';
    const cost = header.length + text.length + 10;
    if (cost > remaining) continue;
    sources.push({ text, source, page, header });
    remaining -= cost;
  }
  const citations = [];
  const citationKeys = new Set();
  for (const source of sources) {
    const key = JSON.stringify([source.source, source.page]);
    if (!citationKeys.has(key)) {
      citationKeys.add(key);
      citations.push({ archivo: source.source, pagina: source.page });
    }
  }
  return [{ json: {
    context: sources.length ? sources.map(source => source.header + source.text).join('\n\n---\n\n') : noContext,
    citations,
    hasContext: sources.length > 0,
    passages: sources.map((source, index) => ({ id: index + 1, text: source.text, archivo: source.source, pagina: source.page }))
  } }];

const retrieved = $('Formatear Contexto').first().json;
const empty = { context: 'No se encontró material relevante sobre el tema en la base de datos.', citations: [], hasContext: false };
if (retrieved.hasContext === false) return [{ json: empty }];
let decision = $json.output;
if (typeof decision === 'string') {
  decision = JSON.parse(decision.trim().replace(/^\x60\x60\x60(?:json)?\s*/i, '').replace(/\s*\x60\x60\x60$/, ''));
}
if (!decision || typeof decision.supported !== 'boolean' || !Array.isArray(decision.sourceIds)) {
  throw new Error('La verificación de respaldo no devolvió una decisión válida.');
}
const ids = decision.sourceIds;
const passages = retrieved.passages;
if (!Array.isArray(passages) || ids.some(id => !Number.isInteger(id) || !passages.some(passage => passage.id === id))) {
  throw new Error('La verificación de respaldo devolvió fuentes inexistentes.');
}
if (!decision.supported) {
  if (ids.length) throw new Error('La verificación rechazó la consulta pero devolvió fuentes.');
  return [{ json: empty }];
}
if (!ids.length) throw new Error('La verificación autorizó una respuesta sin fuentes.');
const selected = passages.filter(passage => ids.includes(passage.id));
const seen = new Set();
const citations = selected.filter(passage => {
  const key = JSON.stringify([passage.archivo, passage.pagina]);
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
}).map(passage => ({ archivo: passage.archivo, pagina: passage.pagina }));
return [{ json: {
  context: selected.map(passage => 'Fuente: ' + passage.archivo + (passage.pagina ? ' (Pág. ' + passage.pagina + ' del PDF)' : '') + '\n' + passage.text).join('\n\n---\n\n'),
  citations, hasContext: true
} }];
